import org.jsoup.Connection;
import org.jsoup.helper.UrlBuilder;
import org.junit.Assert;
import org.junit.Test;
import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;

public class UrlBuilderTest {
    @Test
    public void UrlBuilderConstructor_ValidUrl_NoExceptionThrown() {
        URL url;
        try {
            url = new URL("http://www.google.com");
            UrlBuilder builder = new UrlBuilder(url);
            Assert.assertNotNull(builder);
        } catch (MalformedURLException e) {
            Assert.fail("MalformedURLException should not have been thrown.");
        }
    }

    @Test(expected = NullPointerException.class)
    public void UrlBuilderConstructor_NullUrl_ExceptionThrown() {
        UrlBuilder builder = new UrlBuilder(null);
    }

    @Test
    public void buildUrl_ValidUrl_CorrectURLReturned() {
        try {
            URL url = new URL("http://www.google.com");
            UrlBuilder builder = new UrlBuilder(url);
            URL builtURL = builder.build();
            Assert.assertEquals("http://www.google.com", builtURL.toString());
        } catch (MalformedURLException e) {
            Assert.fail("MalformedURLException should not have been thrown.");
        }
    }

    @Test
    public void appendKeyVal_ValidKeyVal_KeyValAppendedToURL() {
        try {
            URL url = new URL("http://www.google.com");
            UrlBuilder builder = new UrlBuilder(url);
            Connection.KeyVal kv = Connection.KeyVal.create("testKey", "testValue");
            builder.appendKeyVal(kv);
            URL builtURL = builder.build();
            Assert.assertTrue(builtURL.toString().contains("testKey=testValue"));
        } catch (UnsupportedEncodingException ex) {
            Assert.fail("UnsupportedEncodingException should not have been thrown.");
        } catch (MalformedURLException e) {
            Assert.fail("MalformedURLException should not have been thrown.");
        }
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyVal_UnsupportedEncoding_ExceptionThrown() throws UnsupportedEncodingException {
        URL url;
        try {
            url = new URL("http://www.google.com");
            UrlBuilder builder = new UrlBuilder(url);
            Connection.KeyVal kv = Connection.KeyVal.create("testKey", "\uFFFF");
            builder.appendKeyVal(kv);
        } catch (MalformedURLException e) {
            Assert.fail("MalformedURLException should not have been thrown.");
        }
    }
}
